/**
 * A GitHub App installation that has not approved every permission the Remediation Agent requires. Only permissions the
 * app itself requests appear here; a permission the app does not request is reported once in 'appMissingPermissions'
 * instead, because no installation owner can approve it. Suspension alone does not put an installation in this list.
 *
 */
export type AffectedInstallationResource = {
  /**
   * Identifier of the GitHub App installation
   */
  readonly installationId?: string;
  /**
   * Login of whoever the app is installed on. May be an organization or a personal account.
   */
  readonly installationOwner?: string;
  /**
   * URL of the installation settings page, where the missing permissions can be approved
   */
  readonly settingsUrl?: string;
  /**
   * Permissions this installation still has to approve
   */
  readonly missingPermissions?: Array<PermissionDeficitResource>;
};

export type PermissionCheckResource = {
  /**
   * Key of the DevOps Platform configuration
   */
  readonly key?: string;
  /**
   * DevOps Platform type of the configuration (github, gitlab, azure)
   */
  type?: string;
  /**
   * Whether the configuration grants the write permissions the Remediation Agent needs to clone and open pull requests
   */
  status?: 'SUFFICIENT' | 'INSUFFICIENT' | 'UNKNOWN' | 'CHECK_FAILED' | 'UNSUPPORTED_TOKEN_TYPE';
  /**
   * Epoch milliseconds when this status was last computed. May reflect a cached result.
   */
  readonly checkedAt?: number;
  /**
   * GitHub only. Permissions that the GitHub App does not request. Add these permissions to the app before an
   * installation can approve them. If the system cannot read the app configuration, 'status' is CHECK_FAILED. In this
   * case, an empty list means that no app permission result is available.
   *
   */
  readonly appMissingPermissions?: Array<PermissionDeficitResource> | null;
  /**
   * GitHub only. Whether the per-installation scan produced a trustworthy answer. The counts and the list are
   * authoritative only when this is COMPLETE. On a project request, NOT_INSTALLED means the app is not installed on
   * that project's repository — a definite answer, unlike FAILED. NOT_RUN means that the system did not check an
   * installation because the project has no bound repository. In this case, 'status' covers only the app configuration.
   *
   */
  readonly installationCheckStatus?: 'COMPLETE' | 'FAILED' | 'NOT_INSTALLED' | 'NOT_RUN';
  /**
   * GitHub administrator requests only. How many installations the app has at all. Tells an app nobody has installed
   * apart from an app whose installations have all approved, which both report zero affected installations. Omitted
   * unless 'installationCheckStatus' is COMPLETE.
   *
   */
  readonly totalInstallationCount?: number | null;
  /**
   * GitHub administrator requests only. Exact number of installations with missing permissions. Omitted unless
   * 'installationCheckStatus' is COMPLETE.
   *
   */
  readonly affectedInstallationCount?: number | null;
  /**
   * GitHub administrator requests only. Every installation with missing permissions, in a stable order. Omitted unless
   * 'installationCheckStatus' is COMPLETE.
   *
   */
  readonly affectedInstallations?: Array<AffectedInstallationResource> | null;
};

export type PermissionChecksRestResponse = {
  permissionChecks?: Array<PermissionCheckResource>;
};

/**
 * A permission the Remediation Agent requires that is not granted at the level it needs
 */
export type PermissionDeficitResource = {
  /**
   * Name of the DevOps Platform permission, e.g. 'contents'
   */
  readonly permission?: string;
  /**
   * Access level the Remediation Agent requires, e.g. 'write'
   */
  readonly required?: string;
  /**
   * Access level actually granted, or null when the permission is not granted at all
   */
  readonly granted?: string | null;
};

